// InfraestructureServiceServer is the server API for InfraestructureService service.
// All implementations must embed UnimplementedInfraestructureServiceServer
// for forward compatibility.
type InfraestructureServiceServer interface {
	GetAvailableLockerBySize(context.Context, *RequestGetAvailableLockerBySize) (*ResponseGetAvailableLockerBySize, error)
	GetInfraestructureByQR(context.Context, *RequestGetInfraestructureByQR) (*ResponseGetInfraestructureByQR, error)
	GetAvalilableLockersSizeByRackId(context.Context, *RequestGetAvalilableLockersSizeByRackId) (*ResponseGetAvalilableLockersSizeByRackId, error)
	GetInstallationByNumbSerie(context.Context, *RequestGetInstallationByNumbSerie) (*ResponseGetInstallationByNumbSerie, error)
	GetInstallationsByUserEmail(context.Context, *RequestGetInstallationsByUserEmail) (*ResponseGetInstallationsByUserEmail, error)
	// obtener datos de infra asociados a rack segun rack ID
	GetInfraDataByRackID(context.Context, *RequestGetInfraDataByRackID) (*ResponseGetInfraDataByRackID, error)
	// obtener lockers asociados a rack -> objeto debe retornarlos todos e indicar invididualmente si estan habilitados o no
	GetLockersInRackByRackId(context.Context, *ResquestGetLockrsInRackByRackId) (*ResponseGetLockrsInRackByRackId, error)
	// es un servico especial, hace aperturas y en el futuro persistira datos
	OpenLocker(context.Context, *RequestOpenLocker) (*ResponseOpenLocker, error)
	// obtener informacion de todas las infraestructuras
	GetAllInfrastructure(context.Context, *RequestGetAllInfrastructure) (*ResponseGetAllInfrastructure, error)
	// obtener informacion de todos los racks
	GetAllRacks(context.Context, *RequestGetAllRacks) (*ResponseGetAllRacks, error)
	// obtener informacion de todos los devices
	GetAllDevices(context.Context, *RequestGetAllDevices) (*ResponseGetAllDevices, error)
	// eliminar un device por ID (solo si esta offline)
	DeleteDevice(context.Context, *RequestDeleteDevice) (*ResponseDeleteDevice, error)
	// obtener todos los tipos de dispositivos (device_type)
	GetDeviceTypes(context.Context, *RequestGetDeviceTypes) (*ResponseGetDeviceTypes, error)
	// crear un nuevo device
	CreateDevice(context.Context, *RequestCreateDevice) (*ResponseCreateDevice, error)
	// actualizar un device existente
	UpdateDevice(context.Context, *RequestUpdateDevice) (*ResponseUpdateDevice, error)
	// obtener informacion de todas las instalaciones
	GetAllInstallations(context.Context, *RequestGetAllInstallations) (*ResponseGetAllInstallations, error)
	// obtener informacion de todos los qrs
	GetAllQRs(context.Context, *RequestGetAllQRs) (*ResponseGetAllQRs, error)
	// actualizar value y description de un qr existente
	UpdateQR(context.Context, *RequestUpdateQR) (*ResponseUpdateQR, error)
	// obtener todos los lockers de un rack con su informacion de tipo
	GetLockersByRackID(context.Context, *RequestGetLockersByRackID) (*ResponseGetLockersByRackID, error)
	// actualizar el estado activo/inactivo de un locker
	UpdateStatusLocker(context.Context, *RequestUpdateStatusLocker) (*ResponseUpdateStatusLocker, error)
	// actualizar el estado activo/inactivo de multiples lockers a la vez
	UpdateStatusLockersBatch(context.Context, *RequestUpdateStatusLockersBatch) (*ResponseUpdateStatusLockersBatch, error)
	// dado un codigo de dispositivo y un numero de locker, retornar posicion ficticia y real del locker (si no tiene posicion ficticia retorna 0, si hay ficticia retorna la real y la ficticia)
	// ademas retorna el numero de serie del dispositivo (si existe configuracion ficticia retornar valor de columna numb_serie de metadata_device_numb_serie, y si no existe retornar el numero de serie del dispositivo de tabla device)
	GetLockerRealPositionAndFictitiousByDeviceNumberAndLockerPosition(context.Context, *RequestGetLockerRealPositionAndFictitiousByDeviceNumberAndLockerPosition) (*ResponseGetLockerRealPositionAndFictitiousByDeviceNumberAndLockerPosition, error)
	// crear un nuevo qr (sube la imagen a S3 y persiste la URL en la tabla qr)
	CreateQR(context.Context, *RequestCreateQR) (*ResponseCreateQR, error)
	// crear una nueva instalacion (sube la imagen a S3 y persiste la URL en la tabla installation)
	CreateInstallation(context.Context, *RequestCreateInstallation) (*ResponseCreateInstallation, error)
	// crear un nuevo rack
	CreateRack(context.Context, *RequestCreateRack) (*ResponseCreateRack, error)
	// listar todas las administraciones
	GetAdministration(context.Context, *RequestGetAdministration) (*ResponseGetAdministration, error)
	// listar todos los tipos de rack
	GetRackTypes(context.Context, *RequestGetRackTypes) (*ResponseGetRackTypes, error)
	// listar todos los sistemas odihnx
	GetOdihnxSystem(context.Context, *RequestGetOdihnxSystem) (*ResponseGetOdihnxSystem, error)
	// listar todos los tipos de locker
	GetLockerTypes(context.Context, *RequestGetLockerTypes) (*ResponseGetLockerTypes, error)
	// crear un nuevo registro en rack_system (asocia un rack con un sistema odihnx)
	CreateRackSystem(context.Context, *RequestCreateRackSystem) (*ResponseCreateRackSystem, error)
	// crear N lockers en un rack segun las posiciones recibidas
	CreateSetLocker(context.Context, *RequestCreateSetLocker) (*ResponseCreateSetLocker, error)
	// listar todos los meta QRs (tabla metadata_qr) con paginacion y filtro opcional por qr padre
	GetAllMetaQRs(context.Context, *RequestGetAllMetaQRs) (*ResponseGetAllMetaQRs, error)
	// actualizar meta_value y/o qr_id de un meta QR existente
	UpdateMetaQR(context.Context, *RequestUpdateMetaQR) (*ResponseUpdateMetaQR, error)
	mustEmbedUnimplementedInfraestructureServiceServer()
}

